from fastapi.sse import ServerSentEvent
import pytest

def test_sse_validation():
    # Test event newline
    try:
        ServerSentEvent(event="event\nname")
        print("Failed: event with newline should raise ValueError")
    except ValueError as e:
        print(f"Caught expected error for event: {e}")

    # Test event carriage return
    try:
        ServerSentEvent(event="event\rname")
        print("Failed: event with carriage return should raise ValueError")
    except ValueError as e:
        print(f"Caught expected error for event cr: {e}")

    # Test id newline
    try:
        ServerSentEvent(id="id\n123")
        print("Failed: id with newline should raise ValueError")
    except ValueError as e:
        print(f"Caught expected error for id newline: {e}")

    # Test id carriage return
    try:
        ServerSentEvent(id="id\r123")
        print("Failed: id with carriage return should raise ValueError")
    except ValueError as e:
        print(f"Caught expected error for id cr: {e}")

    # Test id null
    try:
        ServerSentEvent(id="id" + chr(0) + "123")
        print("Failed: id with null should raise ValueError")
    except ValueError as e:
        print(f"Caught expected error for id null: {e}")

    # Test valid
    try:
        ServerSentEvent(event="test-event", id="123", data="hello")
        print("Valid event passed")
    except Exception as e:
        print(f"Failed: valid event raised error: {e}")

test_sse_validation()
'
